### `code/src/supabaseClient.ts`
```typescript
import { createClient, type SupabaseClient } from '@supabase/supabase-js';
import { config } from './config.js';

/**
 * Public (anon) client — safe for browser/public use. Access is governed by
 * Row Level Security on the Supabase project.
 */
export const supabase: SupabaseClient = createClient(
  config.supabaseUrl,
  config.supabaseAnonKey,
);

/**
 * Server-only admin client (service-role key). Bypasses RLS — NEVER import this
 * into browser/client code. Created lazily so the app runs without the key set.
 */
let _admin: SupabaseClient | null = null;
export function getAdminClient(): SupabaseClient {
  if (!config.supabaseServiceRoleKey) {
    throw new Error(
      'SUPABASE_SERVICE_ROLE_KEY is not set — admin client unavailable (server-only).',
    );
  }
  if (!_admin) {
    _admin = createClient(config.supabaseUrl, config.supabaseServiceRoleKey, {
      auth: { autoRefreshToken: false, persistSession: false },
    });
  }
  return _admin;
}
```

