### `code/src/storage.ts`
```typescript
import { supabase } from './supabaseClient.js';
import { config } from './config.js';

const bucket = () => supabase.storage.from(config.storageBucket);

/** Upload a file/blob to `path` in the default bucket. */
export async function upload(
  path: string,
  file: File | Blob | ArrayBuffer | Buffer,
  opts?: { upsert?: boolean; contentType?: string },
) {
  return bucket().upload(path, file, {
    upsert: opts?.upsert ?? false,
    contentType: opts?.contentType,
  });
}

/** Download a file at `path` as a Blob. */
export async function download(path: string) {
  return bucket().download(path);
}

/** List objects under an optional prefix. */
export async function list(prefix = '') {
  return bucket().list(prefix);
}

/** Remove one or more objects by path. */
export async function remove(paths: string[]) {
  return bucket().remove(paths);
}

/** Public URL for an object (only meaningful for public buckets). */
export function getPublicUrl(path: string) {
  return bucket().getPublicUrl(path);
}

/** Time-limited signed URL for a private object. */
export async function createSignedUrl(path: string, expiresInSeconds = 3600) {
  return bucket().createSignedUrl(path, expiresInSeconds);
}
